local a={}a.CFG={degPerCell=3,tickEvery=10,labelEvery=30,tickCh="|"}local b={[0]="N",[90]="E",[180]="S",[270]="W"}local function c(d)return math.floor(d+0.5)end;function a.norm360(e)local f=e%360;if f<0 then f=f+360 end;return f end;function a.signedDelta(g,h)return(g-h+180)%360-180 end;function a.lubberCol(i)return math.ceil(i/2)end;function a.lubberLabel(j)if type(j)~="number"then return"---"end;return string.format("%03d",c(a.norm360(j))%360)end;local function k(l,m,n)for o=1,#n do local p=m+o-1;if p>=1 and p<=#l then l[p]=n:sub(o,o)end end end;function a.bugCol(q,j,i,r)r=r or a.CFG;if type(q)~="number"or type(j)~="number"or type(i)~="number"or i<1 then return nil end;local m=a.lubberCol(i)+c(a.signedDelta(q,j)/r.degPerCell)if m<1 or m>i then return nil end;return m end;function a.row(j,i,r)r=r or a.CFG;if type(i)~="number"or i<1 then return""end;if type(j)~="number"then return string.rep(" ",i)end;local l={}for o=1,i do l[o]=" "end;local s=a.lubberCol(i)local t=math.floor(i/2)*r.degPerCell+r.labelEvery;local u=c(j/r.tickEvery)*r.tickEvery;for v=u-t,u+t,r.tickEvery do local m=s+c(a.signedDelta(v,j)/r.degPerCell)k(l,m,r.tickCh)end;local w=c(j/r.labelEvery)*r.labelEvery;for v=w-t,w+t,r.labelEvery do local x=a.norm360(v)local y=b[x]or string.format("%02d",c(x/10)%36)local m=s+c(a.signedDelta(v,j)/r.degPerCell)k(l,m-math.floor(#y/2),y)end;return table.concat(l)end;return a